using System.ComponentModel.DataAnnotations;
using BofcBackend.Api.Domain.Entities;
using BofcBackend.Api.Features.Settings.Models;

// SPEC: spec-a6f59e - the "Auto generated match number" setting defaults to 2 before it has
// ever been saved, and PUT settings accepts only 1 to 8 for it.
public static class AutoGeneratedMatchNumberTests
{
    public static (string Name, Func<Task> Run)[] All =>
    [
        ("auto generated match number defaults to 2 when never saved", async () =>
        {
            AssertEqual(2, new SystemSettings().AutoGeneratedMatchNumber, "SystemSettings");
            AssertEqual(2, new UpdateSystemSettingsRequest().AutoGeneratedMatchNumber, "UpdateSystemSettingsRequest");
            AssertEqual(2, new SystemSettingsResponse().AutoGeneratedMatchNumber, "SystemSettingsResponse");
        }),
        ("auto generated match number rejects 0 and 9", async () =>
        {
            foreach (var value in new[] { 0, 9 })
            {
                if (IsValid(value))
                {
                    throw new Exception($"expected {value} to be rejected, but it validated");
                }
            }
        }),
        ("auto generated match number accepts 1 to 8", async () =>
        {
            for (var value = 1; value <= 8; value++)
            {
                if (!IsValid(value))
                {
                    throw new Exception($"expected {value} to be accepted, but it was rejected");
                }
            }
        }),
    ];

    // The same check [ApiController] model validation runs on PUT settings before the action.
    private static bool IsValid(int autoGeneratedMatchNumber)
    {
        var request = new UpdateSystemSettingsRequest { AutoGeneratedMatchNumber = autoGeneratedMatchNumber };
        var results = new List<ValidationResult>();
        Validator.TryValidateObject(request, new ValidationContext(request), results, validateAllProperties: true);
        return !results.Any(r => r.MemberNames.Contains(nameof(UpdateSystemSettingsRequest.AutoGeneratedMatchNumber)));
    }

    private static void AssertEqual(int expected, int actual, string source)
    {
        if (actual != expected)
        {
            throw new Exception($"{source}: expected {expected}, got {actual}");
        }
    }
}
